// ❌ OLD: Every protected page must remember to check auth itself.
// Forgetting one page leaks it, and the check runs after the page
// starts rendering.
import { getSession } from '@/lib/session';
import { redirect } from 'next/navigation';

export default async function DashboardPage() {
  // ❌ OLD: per-page guard — easy to forget on the next page
  const session = await getSession();
  if (!session) redirect('/login');

  return <main>Dashboard for {session.user.name}</main>;
}

// SettingsPage, AdminPage, ProfilePage... each needs the same copy.

