import { NextRequest, NextResponse } from 'next/server';

// ✅ NEW: One guard for all protected routes, running before any page
// or API route executes.
export function middleware(request: NextRequest) {
  const session = request.cookies.get('session'); // ✅ NEW: cookie check
  if (!session) {
    return NextResponse.redirect(new URL('/login', request.url)); // ✅ NEW
  }

  // ✅ NEW: rewrite the response to stamp a header (e.g. geolocation)
  const response = NextResponse.next();
  response.headers.set('x-request-id', crypto.randomUUID());
  return response;
}

export const config = {
  matcher: ['/dashboard/:path*', '/settings/:path*'], // ✅ NEW: scoped paths
};
